// Seals a secret with this Linux machine's TPM 2.0, by sending TPM commands
// to the kernel's resource manager (`/dev/tpmrm0`) directly, so there's no
// native code or library (tpm2-tss) to install.
//
// The secret goes into a sealed data object under the owner hierarchy's
// storage key. The TPM derives that storage key from a seed that never
// leaves it, the same way every time, so nothing is kept in the TPM: what we
// save is the object's public area and its private area, which the TPM
// encrypted with that storage key and which only this TPM can load.
//
// The commands use password sessions with empty passwords, without
// parameter encryption, so the secret crosses the bus between the CPU and a
// discrete TPM in the clear when it's sealed and unsealed. That's within
// what sealing protects against (a copied login), not a physical attacker.
//
// Buffers that held the secret are zeroed once they're used. That's best
// effort: JavaScript can keep other copies, and the caller turns the secret
// into a key.

import { closeSync, existsSync, openSync, readSync, writeSync } from 'node:fs';

export const TPM_DEVICE = '/dev/tpmrm0';

/** A connection to a TPM: sends a command and returns its response. */
export interface TpmConnection {
  transmit(command: Buffer): Buffer;
  close(): void;
}

export type ConnectTpm = () => TpmConnection;

// Constants from the TPM 2.0 Library spec, Part 2.
const TPM_ST_NO_SESSIONS = 0x8001;
const TPM_ST_SESSIONS = 0x8002;
const TPM_CC_CREATE_PRIMARY = 0x131;
const TPM_CC_CREATE = 0x153;
const TPM_CC_LOAD = 0x157;
const TPM_CC_UNSEAL = 0x15e;
const TPM_CC_FLUSH_CONTEXT = 0x165;
const TPM_RH_OWNER = 0x40000001;
const TPM_RS_PW = 0x40000009;
const TPM_ALG_AES = 0x0006;
const TPM_ALG_KEYEDHASH = 0x0008;
const TPM_ALG_SHA256 = 0x000b;
const TPM_ALG_NULL = 0x0010;
const TPM_ALG_ECC = 0x0023;
const TPM_ALG_CFB = 0x0043;
const TPM_ECC_NIST_P256 = 0x0003;
const FIXED_TPM = 1 << 1;
const FIXED_PARENT = 1 << 4;
const SENSITIVE_DATA_ORIGIN = 1 << 5;
const USER_WITH_AUTH = 1 << 6;
const NO_DA = 1 << 10;
const RESTRICTED = 1 << 16;
const DECRYPT = 1 << 17;
// The TPM is busy: send the command again.
const TPM_RC_RETRY = 0x922;
const TPM_RC_YIELDED = 0x908;
const TPM_RC_TESTING = 0x90a;
const MAX_RETRIES = 10;
// How long to wait before sending a command again, times the attempt.
const RETRY_DELAY_MS = 50;
// Format-one response codes (bit 7 set) carry an error number in their low
// six bits: TPM_RC_BAD_AUTH and TPM_RC_AUTH_FAIL mean a wrong password.
const RC_FMT1 = 0x080;
const RC_BAD_AUTH = 0x022;
const RC_AUTH_FAIL = 0x00e;
const MAX_RESPONSE_SIZE = 4096;

// The storage key's template: the TCG's standard ECC P-256 SRK template, so
// the TPM derives the same key from the owner seed every time.
const STORAGE_KEY_TEMPLATE = tpm2b(
  concat([
    u16(TPM_ALG_ECC),
    u16(TPM_ALG_SHA256),
    u32(
      FIXED_TPM |
        FIXED_PARENT |
        SENSITIVE_DATA_ORIGIN |
        USER_WITH_AUTH |
        NO_DA |
        RESTRICTED |
        DECRYPT
    ),
    tpm2b(Buffer.alloc(0)), // authPolicy
    u16(TPM_ALG_AES),
    u16(128),
    u16(TPM_ALG_CFB),
    u16(TPM_ALG_NULL), // scheme
    u16(TPM_ECC_NIST_P256),
    u16(TPM_ALG_NULL), // kdf
    tpm2b(Buffer.alloc(0)), // unique.x
    tpm2b(Buffer.alloc(0)), // unique.y
  ])
);

// The sealed object's template: data only this TPM can load, and only under
// this storage key, unsealed with an empty password.
const SEALED_OBJECT_TEMPLATE = tpm2b(
  concat([
    u16(TPM_ALG_KEYEDHASH),
    u16(TPM_ALG_SHA256),
    u32(FIXED_TPM | FIXED_PARENT | USER_WITH_AUTH | NO_DA),
    tpm2b(Buffer.alloc(0)), // authPolicy
    u16(TPM_ALG_NULL), // scheme
    tpm2b(Buffer.alloc(0)), // unique
  ])
);

export class LinuxTpmError extends Error {
  constructor(
    what: string,
    readonly rc: number,
    reason = ''
  ) {
    super(`${reason}${what} failed with 0x${rc.toString(16)}.`);
  }
}

/** This user isn't allowed to open the TPM device. */
export class TpmAccessError extends Error {
  constructor() {
    super(
      `Your user can't open ${TPM_DEVICE}. The group that owns it (usually tss) can, but joining it gives your user access to the rest of the TPM too, so only join it if that's fine on this machine.`
    );
  }
}

/** Whether this machine has a TPM the kernel exposes to user space. */
export function hasLinuxTpm(): boolean {
  return existsSync(TPM_DEVICE);
}

/**
 * Seal `secret` with this machine's TPM. Returns the sealed object's public
 * area and its private area, encrypted by the TPM, both as TPM2B structures.
 */
export function sealWithLinuxTpm(
  secret: Buffer,
  connect: ConnectTpm = connectToDevice
): { public: Buffer; private: Buffer } {
  return withStorageKey(connect, (tpm, parent) => {
    const data = tpm2b(secret);
    const body = concat([tpm2b(Buffer.alloc(0)), data]);
    const sensitive = tpm2b(body);
    const cmd = command(TPM_CC_CREATE, parent, [
      sensitive,
      SEALED_OBJECT_TEMPLATE,
      tpm2b(Buffer.alloc(0)), // outsideInfo
      u32(0), // creationPCR
    ]);
    for (const copy of [data, body, sensitive]) {
      copy.fill(0);
    }
    let response: Buffer;
    try {
      response = send(tpm, 'TPM2_Create', cmd);
    } finally {
      cmd.fill(0);
    }
    // Header, then parameterSize, then outPrivate and outPublic.
    const sealedPrivate = readTpm2b(response, 14);
    const sealedPublic = readTpm2b(response, 14 + sealedPrivate.length);
    return { public: sealedPublic, private: sealedPrivate };
  });
}

/** Unseal what `sealWithLinuxTpm` sealed, with this machine's TPM. */
export function unsealWithLinuxTpm(
  sealed: { public: Buffer; private: Buffer },
  connect: ConnectTpm = connectToDevice
): Buffer {
  return withStorageKey(connect, (tpm, parent) => {
    const object = send(
      tpm,
      'TPM2_Load',
      command(TPM_CC_LOAD, parent, [sealed.private, sealed.public])
    ).readUInt32BE(10);
    try {
      const response = send(
        tpm,
        'TPM2_Unseal',
        command(TPM_CC_UNSEAL, object, [])
      );
      const outData = readTpm2b(response, 14);
      const secret = Buffer.from(new Uint8Array(outData.subarray(2)));
      outData.fill(0);
      response.fill(0);
      return secret;
    } finally {
      flush(tpm, object);
    }
  });
}

function withStorageKey<T>(
  connect: ConnectTpm,
  fn: (tpm: TpmConnection, parent: number) => T
): T {
  const tpm = connect();
  try {
    let parent: number;
    try {
      parent = send(
        tpm,
        'TPM2_CreatePrimary',
        command(TPM_CC_CREATE_PRIMARY, TPM_RH_OWNER, [
          // inSensitive: no password, no data.
          tpm2b(concat([tpm2b(Buffer.alloc(0)), tpm2b(Buffer.alloc(0))])),
          STORAGE_KEY_TEMPLATE,
          tpm2b(Buffer.alloc(0)), // outsideInfo
          u32(0), // creationPCR
        ])
      ).readUInt32BE(10);
    } catch (error) {
      if (error instanceof LinuxTpmError && isWrongPassword(error.rc)) {
        throw new LinuxTpmError(
          'TPM2_CreatePrimary',
          error.rc,
          "This TPM's owner hierarchy has a password, which the CLI doesn't use: "
        );
      }
      throw error;
    }
    try {
      return fn(tpm, parent);
    } finally {
      flush(tpm, parent);
    }
  } finally {
    // The resource manager also flushes what this connection loaded.
    tpm.close();
  }
}

function isWrongPassword(rc: number): boolean {
  const error = rc & 0x3f;
  return (
    (rc & RC_FMT1) !== 0 && (error === RC_BAD_AUTH || error === RC_AUTH_FAIL)
  );
}

function flush(tpm: TpmConnection, handle: number): void {
  try {
    const body = u32(handle);
    send(
      tpm,
      'TPM2_FlushContext',
      concat([
        u16(TPM_ST_NO_SESSIONS),
        u32(10 + body.length),
        u32(TPM_CC_FLUSH_CONTEXT),
        body,
      ])
    );
  } catch {
    // Closing the connection flushes it anyway.
  }
}

// A command with one handle, authorized by an empty password.
function command(code: number, handle: number, parameters: Buffer[]): Buffer {
  const auth = concat([
    u32(TPM_RS_PW),
    tpm2b(Buffer.alloc(0)), // nonce
    Buffer.from([0]), // sessionAttributes
    tpm2b(Buffer.alloc(0)), // password
  ]);
  const body = concat([u32(handle), u32(auth.length), auth, ...parameters]);
  const cmd = concat([
    u16(TPM_ST_SESSIONS),
    u32(10 + body.length),
    u32(code),
    body,
  ]);
  // It may hold a secret.
  body.fill(0);
  return cmd;
}

function send(tpm: TpmConnection, what: string, cmd: Buffer): Buffer {
  for (let attempt = 0; ; attempt++) {
    const response = tpm.transmit(cmd);
    if (response.length < 10 || response.readUInt32BE(2) !== response.length) {
      throw new Error(`${what} returned a malformed response.`);
    }
    const rc = response.readUInt32BE(6);
    if (rc === 0) {
      return response;
    }
    const busy =
      rc === TPM_RC_RETRY || rc === TPM_RC_YIELDED || rc === TPM_RC_TESTING;
    if (!busy || attempt >= MAX_RETRIES) {
      throw new LinuxTpmError(what, rc);
    }
    sleep(RETRY_DELAY_MS * (attempt + 1));
  }
}

// Wait without returning to the event loop: every TPM call is synchronous.
function sleep(ms: number): void {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

function connectToDevice(): TpmConnection {
  let fd: number;
  try {
    fd = openSync(TPM_DEVICE, 'r+');
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === 'EACCES' || code === 'EPERM') {
      throw new TpmAccessError();
    }
    throw error;
  }
  return {
    transmit(cmd) {
      writeSync(fd, view(cmd));
      // The kernel returns the whole response in one read.
      const response = Buffer.alloc(MAX_RESPONSE_SIZE);
      const size = readSync(fd, view(response), 0, response.length, null);
      const result = Buffer.from(new Uint8Array(response.subarray(0, size)));
      response.fill(0);
      return result;
    },
    close() {
      closeSync(fd);
    },
  };
}

// A TPM2B structure (a 16-bit size, then that many bytes) at `offset`,
// including its size.
function readTpm2b(buffer: Buffer, offset: number): Buffer {
  const end = offset + 2 + buffer.readUInt16BE(offset);
  if (end > buffer.length) {
    throw new Error('The TPM returned a truncated response.');
  }
  return Buffer.from(new Uint8Array(buffer.subarray(offset, end)));
}

function tpm2b(bytes: Buffer): Buffer {
  return concat([u16(bytes.length), bytes]);
}

function concat(parts: Buffer[]): Buffer {
  const result = Buffer.alloc(parts.reduce((size, p) => size + p.length, 0));
  let offset = 0;
  for (const part of parts) {
    result.set(part, offset);
    offset += part.length;
  }
  return result;
}

// A view `fs` accepts, whichever `@types/node` is installed.
function view(buffer: Buffer): Uint8Array {
  return new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.length);
}

function u16(value: number): Buffer {
  const bytes = Buffer.alloc(2);
  bytes.writeUInt16BE(value);
  return bytes;
}

function u32(value: number): Buffer {
  const bytes = Buffer.alloc(4);
  bytes.writeUInt32BE(value >>> 0);
  return bytes;
}
